INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(93263, 'ruRU', 'Я знаю, зачем ты здесь, малыш...', '', 24330),
(93265, 'ruRU', 'Прошу... помоги...', '', 24330),
(93266, 'ruRU', 'Вы, смертные, с вашей гордыней. Вы сгорите в моём пламени!', '', 24330),
(93267, 'ruRU', 'Я вернусь!', '', 24330),
(93268, 'ruRU', 'А, величайший защитник Света явился, чтобы заполучить святой Пеплосерд и истребить мой род.', '', 24330),
(93269, 'ruRU', 'Я ждал тебя, паладин. Знай: я вырву душу из твоей плоти и сделаю твоё тело своим.', '', 24330),
(93271, 'ruRU', 'Свет всегда одержит победу над тьмой.', '', 24330),
(93272, 'ruRU', 'Сожгите всё, мои питомцы. Не оставляйте ничего, кроме пепла.', '', 24330),
(93273, 'ruRU', 'Я ВЕРНУСЬ!', '', 24330),
(93278, 'ruRU', 'Ах, $p. Хорошо. Мне нужен кто-то с более холодной головой, чем Мариус.$b$bЭто место идеально подходит для призыва демона, более могущественного, чем любой, кого я призывал раньше.$b$bМне нужно, чтобы ты проследил, что этот охотник на демонов не натворит глупостей вроде убийства демона прежде, чем я успею принудить его к покорности.$b$bТы встанешь на мою сторону?', '', 24330),
(93279, 'ruRU', 'Ладно...?', '', 24330),
(93280, 'ruRU', 'Твоя трусость налицо, Мариус. Мы должны узнать пределы возможностей врага, если хотим победить его.', '', 24330),
(93281, 'ruRU', 'Кто смеет призывать меня?', '', 24330),
(93282, 'ruRU', 'Нам и без твоего призыва хватает демонов для убийства.', '', 24330),
(93283, 'ruRU', 'Слишком большой! Слишком большой! УБЕЙТЕ ЕГО!', '', 24330),
(93284, 'ruRU', 'В следующий раз нужно не забыть подготовить камень души.', '', 24330),
(93285, 'ruRU', 'Не сейчас, друг мой. Не сейчас.', '', 24330),
(93286, 'ruRU', 'Активировать', '', 24330),
(93287, 'ruRU', 'Легион выбрал своего защитника!', '', 24330),
(93288, 'ruRU', 'Тебе здесь не рады!', '', 24330),
(93289, 'ruRU', 'За Короля-бога!', '', 24330),
(93290, 'ruRU', 'Эгида будет принадлежать Королю-богу!', '', 24330),
(93291, 'ruRU', 'Король-бог повелевает твоей смертью!', '', 24330),
(93292, 'ruRU', 'Ты не достоин испытаний! Слава Королю-богу!', '', 24330),
(93293, 'ruRU', 'Никто не бросит вызов Королю-богу!', '', 24330),
(93294, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Balnazzar.blp:50:80|t$b[Балназар] Ты правда думаешь, что можешь противостоять мне? Моя бесчисленная стража Скверны изрубит тебя.', '', 24330),
(93295, 'ruRU', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Balnazzar.blp:50:80|t$b[Балназар] Впечатляюще... но этого недостаточно. Инферналы, сокрушите их.', '', 24330),
(93296, 'ruRU', 'Довольно. Никогда больше этот проклятый клинок не убьёт моих собратьев! ТЫ... УМРЁШЬ!', '', 24330),
(93297, 'ruRU', 'ХАХА!! Теперь, когда я поглотил кровь своих братьев, у меня хватит сил уничтожить и тебя, и Короля-бога!', '', 24330),
(93300, 'ruRU', '<У странного гномьего робота один глаз болтается, вывалившись из гнезда. Картонная табличка на груди гласит: "БЕТА". Большая часть проводки держится на скотче. Внезапно он заговаривает дребезжащим голосом:>$b$bПриветствую, путешестве-е-е-*щёлк*! Вв-в-в-*клац* ПАРАМЕТРЫ ТЕСТА ПЕРЕЗАГРУЗКА 001011010 Приветствую, путешественник!', '', 24330),
(93302, 'ruRU', '$p, ты должен немедленно прийти. Тирион звал тебя по имени. Боюсь, ему недолго осталось в этом мире. Поспеши!', '', 24330),
(93303, 'ruRU', 'Защитите Решада.', '', 24330),
(93304, 'ruRU', 'БЕТА: Запустить вторжение', '', 24330);
